// GetURL returns the project or the download URL of a well-known plugin.
func GetURL(name string) string {
	switch name {
	case "kms":
		return "https://github.com/smallstep/step-kms-plugin"
	default:
		return ""
	}
}

func Completion(ctx *cli.Context) error {
	if err := errs.NumberOfArguments(ctx, 1); err != nil {
		return err
	}

	shell := ctx.Args().First()

	switch shell {
	case "bash":
		fmt.Print(bash)
	case "zsh":
		fmt.Print(zsh)
	case "fish":
		fish, err := ctx.App.ToFishCompletion()
		if err != nil {
			return fmt.Errorf("error creating fish completion: %w", err)
		}
		fmt.Print(fish)
	default:
		return errors.Errorf("unsupported shell %s", shell)
	}

	return nil
}

