func initAction(ctx *cli.Context) (err error) {
	if err := assertCryptoRand(); err != nil {
		return err
	}

	var rootCrt *x509.Certificate
	var rootKey interface{}

	caURL := ctx.String("with-ca-url")
	root := ctx.String("root")
	key := ctx.String("key")
	ra := strings.ToLower(ctx.String("ra"))
	kmsName := strings.ToLower(ctx.String("kms"))
	pkiOnly := ctx.Bool("pki")
	noDB := ctx.Bool("no-db")
	helm := ctx.Bool("helm")
	enableRemoteManagement := ctx.Bool("remote-management")
	addDefaultACMEProvisioner := ctx.Bool("acme")
	firstSuperAdminSubject := ctx.String("admin-subject")

	switch {
	case root != "" && key == "":
		return errs.RequiredWithFlag(ctx, "root", "key")
	case root == "" && key != "":
		return errs.RequiredWithFlag(ctx, "key", "root")
	case root != "" && key != "":
		opts := []pemutil.Options{}
		if keyPasswordFile := ctx.String("key-password-file"); keyPasswordFile != "" {
			opts = append(opts, pemutil.WithPasswordFile(keyPasswordFile))
		}
		if rootCrt, err = pemutil.ReadCertificate(root); err != nil {
			return err
		}
		if rootKey, err = pemutil.Read(key, opts...); err != nil {
			return err
		}
	case ra != "" && ra != apiv1.CloudCAS && ra != apiv1.StepCAS:
		return errs.InvalidFlagValue(ctx, "ra", ctx.String("ra"), "StepCAS or CloudCAS")
	case kmsName != "" && kmsName != "azurekms":
		return errs.InvalidFlagValue(ctx, "kms", ctx.String("kms"), "azurekms")
	case kmsName != "" && ra != "":
		return errs.IncompatibleFlagWithFlag(ctx, "kms", "ra")
	case pkiOnly && noDB:
		return errs.IncompatibleFlagWithFlag(ctx, "pki", "no-db")
	case pkiOnly && helm:
		return errs.IncompatibleFlagWithFlag(ctx, "pki", "helm")
	case enableRemoteManagement && noDB:
		// remote management via the Admin API requires a database configuration
		return errs.IncompatibleFlagWithFlag(ctx, "remote-management", "no-db")
	case addDefaultACMEProvisioner && noDB:
		// ACME functionality requires a database configuration
		return errs.IncompatibleFlagWithFlag(ctx, "acme", "no-db")
	case firstSuperAdminSubject != "" && helm:
		// providing the first super admin subject is not (yet) supported with Helm output
		return errs.IncompatibleFlagWithFlag(ctx, "admin-subject", "helm")
	case firstSuperAdminSubject != "" && !enableRemoteManagement:
		// providing the first super admin subject only works with DB-backed provisioners,
		// thus remote management should be enabled.
		return errors.New("flag '--admin-subject' is only supported when '--remote-management' is enabled")
	}

	var password string
	if passwordFile := ctx.String("password-file"); passwordFile != "" {
		password, err = utils.ReadStringPasswordFromFile(passwordFile)
		if err != nil {
			return err
		}
	}

	// Provisioner password will be equal to the certificate private keys if
	// --provisioner-password-file is not provided.
	var provisionerPassword []byte
	if passwordFile := ctx.String("provisioner-password-file"); passwordFile != "" {
		provisionerPassword, err = utils.ReadPasswordFromFile(passwordFile)
		if err != nil {
			return err
		}
	}

	useContext := cautils.UseContext(ctx)
	if !useContext {
		cautils.WarnContext()
	}

	// Common for both CA and RA

	var name, org, resource string
	var casOptions apiv1.Options
	var deploymentType pki.DeploymentType
	var pkiOpts []pki.Option
	switch ra {
	case apiv1.CloudCAS:
		var create bool
		var project, location, caPool, caPoolTier, gcsBucket string

		caPoolTiers := []struct {
			Name  string
			Value string
		}{{"DevOps", "DEVOPS"}, {"Enterprise", "ENTERPRISE"}}

		// Prompt or get deployment type from flag
		deploymentType, err = promptDeploymentType(ctx, true)
		if err != nil {
			return err
		}

		iss := ctx.String("issuer")
		if iss == "" {
			create, err = ui.PromptYesNo("Would you like to create a new PKI (y) or use an existing one (n)?")
			if err != nil {
				return err
			}
			if create {
				ui.Println("What would you like to name your new PKI?", ui.WithValue(ctx.String("name")))
				name, err = ui.Prompt("(e.g. Smallstep)",
					ui.WithValidateNotEmpty(), ui.WithValue(ctx.String("name")))
				if err != nil {
					return err
				}
				ui.Println("What is the name of your organization?")
				org, err = ui.Prompt("(e.g. Smallstep)",
					ui.WithValidateNotEmpty())
				if err != nil {
					return err
				}
				ui.Println("What resource id do you want to use? [we will append -Root-CA or -Intermediate-CA]")
				resource, err = ui.Prompt("(e.g. Smallstep)",
					ui.WithValidateRegexp("^[a-zA-Z0-9-_]+$"))
				if err != nil {
					return err
				}
				ui.Println("What is the id of your project on Google's Cloud Platform?")
				project, err = ui.Prompt("(e.g. smallstep-ca)",
					ui.WithValidateRegexp("^[a-z][a-z0-9-]{4,28}[a-z0-9]$"))
				if err != nil {
					return err
				}
				ui.Println("What region or location do you want to use?")
				location, err = ui.Prompt("(e.g. us-west1)",
					ui.WithValidateRegexp("^[a-z0-9-]+$"))
				if err != nil {
					return err
				}
				ui.Println("What CA pool name do you want to use?")
				caPool, err = ui.Prompt("(e.g. Smallstep)",
					ui.WithValidateRegexp("^[a-zA-Z0-9_-]{1,63}"))
				if err != nil {
					return err
				}
				i, _, err := ui.Select("What CA pool tier do you want to use?", caPoolTiers, ui.WithSelectTemplates(ui.NamedSelectTemplates("Tier")))
				if err != nil {
					return err
				}
				caPoolTier = caPoolTiers[i].Value
				ui.Println("What GCS bucket do you want to use? Leave it empty to use a managed one.")
				gcsBucket, err = ui.Prompt("(e.g. my-bucket)", ui.WithValidateRegexp("(^$)|(^[a-z0-9._-]{3,222}$)"))
				if err != nil {
					return err
				}
			} else {
				ui.Println("What certificate authority would you like to use?")
				iss, err = ui.Prompt("(e.g. projects/smallstep-ca/locations/us-west1/caPools/smallstep/certificateAuthorities/intermediate-ca)",
					ui.WithValidateRegexp("^projects/[a-z][a-z0-9-]{4,28}[a-z0-9]/locations/[a-z0-9-]+/caPools/[a-zA-Z0-9-_]+/certificateAuthorities/[a-zA-Z0-9-_]+$"))
				if err != nil {
					return err
				}
			}
		}
		casOptions = apiv1.Options{
			Type:                 apiv1.CloudCAS,
			CredentialsFile:      ctx.String("credentials-file"),
			CertificateAuthority: iss,
			IsCreator:            create,
			Project:              project,
			Location:             location,
			CaPool:               caPool,
			CaPoolTier:           caPoolTier,
			GCSBucket:            gcsBucket,
		}
	case apiv1.StepCAS:
		deploymentType, err = promptDeploymentType(ctx, true)
		if err != nil {
			return err
		}
		ui.Println("What is the url of your CA?", ui.WithValue(ctx.String("issuer")))
		ca, err := ui.Prompt("(e.g. https://ca.smallstep.com:9000)",
			ui.WithValidateRegexp("(?i)^https://.+$"), ui.WithValue(ctx.String("issuer")))
		if err != nil {
			return err
		}
		ui.Println("What is the fingerprint of the CA's root file?", ui.WithValue(ctx.String("issuer-fingerprint")))
		fingerprint, err := ui.Prompt("(e.g. 4fe5f5ef09e95c803fdcb80b8cf511e2a885eb86f3ce74e3e90e62fa3faf1531)",
			ui.WithValidateRegexp("^[a-fA-F0-9]{64}$"), ui.WithValue(ctx.String("issuer-fingerprint")))
		if err != nil {
			return err
		}
		ui.Println("What is the JWK provisioner you want to use?", ui.WithValue(ctx.String("issuer-provisioner")))
		provisioner, err := ui.Prompt("(e.g. you@smallstep.com)",
			ui.WithValidateNotEmpty(), ui.WithValue(ctx.String("issuer-provisioner")))
		if err != nil {
			return err
		}
		casOptions = apiv1.Options{
			Type:                            apiv1.StepCAS,
			IsCreator:                       false,
			IsCAGetter:                      true,
			CertificateAuthority:            ca,
			CertificateAuthorityFingerprint: fingerprint,
			CertificateIssuer: &apiv1.CertificateIssuer{
				Type:        "JWK",
				Provisioner: provisioner,
			},
		}
	default:
		deploymentType, err = promptDeploymentType(ctx, false)
		if err != nil {
			return err
		}
		if deploymentType == pki.HostedDeployment {
			ui.Println()
			ui.Println("To use a Hosted authority, you'll need a Smallstep account. To create one,")
			ui.Println("visit:\n")
			ui.Println("    \033[1mhttps://u.step.sm/hosted\033[0m\n")
			ui.Println("Then, to connect to your hosted authority, run:\n")
			ui.Println("    $ step ca bootstrap --team <name> --authority <authority>")
			ui.Println()
			return nil
		}
		// When initializing a linked CA, providing the --acme flag doesn't currently
		// result in the default ACME provisioner being added. We may want to support this
		// for ease of use, but this seems to require a bit of refactoring when generating
		// the full CA configuration with DB initialization.
		if deploymentType != pki.StandaloneDeployment && addDefaultACMEProvisioner {
			return fmt.Errorf("adding a default ACME provisioner by providing the --acme flag is not supported with deployment type %q.\nPlease use `step ca provisioner add acme --type ACME` after initializing your CA", deploymentType.String())
		}

		ui.Println("What would you like to name your new PKI?", ui.WithValue(ctx.String("name")))
		name, err = ui.Prompt("(e.g. Smallstep)", ui.WithValidateNotEmpty(), ui.WithValue(ctx.String("name")))
		if err != nil {
			return err
		}

		// Get names for key managers keys.
		// Currently only azure is supported.
		var keyManager kms.KeyManager
		if kmsName != "" {
			var rootURI, intermediateURI, sshHostURI, sshUserURI string
			keyManager, err = kms.New(context.Background(), kms.Options{
				Type: kms.Type(kmsName),
			})
			if err != nil {
				return err
			}

			var validateFunc func(s string) error
			if v, ok := keyManager.(interface{ ValidateName(s string) error }); ok {
				validateFunc = v.ValidateName
			} else {
				validateFunc = func(_ string) error {
					return nil
				}
			}

			if rootKey == nil {
				ui.Println("What URI would you like to use for the root certificate key?", ui.WithValue(ctx.String("kms-root")))
				rootURI, err = ui.Prompt("(e.g. azurekms:name=my-root-key;vault=my-vault)",
					ui.WithValidateFunc(validateFunc), ui.WithValue(ctx.String("kms-root")))
				if err != nil {
					return err
				}
			}

			ui.Println("What URI would you like to use for the intermediate certificate key?", ui.WithValue(ctx.String("kms-intermediate")))
			intermediateURI, err = ui.Prompt("(e.g. azurekms:name=my-intermediate-key;vault=my-vault)",
				ui.WithValidateFunc(validateFunc), ui.WithValue(ctx.String("kms-intermediate")))
			if err != nil {
				return err
			}

			if ctx.Bool("ssh") {
				ui.Println("What URI would you like to use for the SSH host key?", ui.WithValue(ctx.String("kms-ssh-host")))
				sshHostURI, err = ui.Prompt("(e.g. azurekms:name=my-host-key;vault=my-vault)",
					ui.WithValidateFunc(validateFunc), ui.WithValue(ctx.String("kms-ssh-host")))
				if err != nil {
					return err
				}

				ui.Println("What URI would you like to use for the SSH user key?", ui.WithValue(ctx.String("kms-ssh-user")))
				sshUserURI, err = ui.Prompt("(e.g. azurekms:name=my-user-key;vault=my-vault)",
					ui.WithValidateFunc(validateFunc), ui.WithValue(ctx.String("kms-ssh-user")))
				if err != nil {
					return err
				}
			}

			// Add uris to the pki options. Empty URIs will be ignored.
			pkiOpts = append(pkiOpts, pki.WithKMS(kmsName),
				pki.WithKeyURIs(rootURI, intermediateURI, sshHostURI, sshUserURI))
		}

		// set org and resource to pki name
		org, resource = name, name

		casOptions = apiv1.Options{
			Type:       apiv1.SoftCAS,
			IsCreator:  true,
			KeyManager: keyManager,
		}
	}

	if pkiOnly {
		pkiOpts = append(pkiOpts, pki.WithPKIOnly())
	} else {
		ui.Println("What DNS names or IP addresses will clients use to reach your CA?",
			ui.WithSliceValue(ctx.StringSlice("dns")))
		dnsValue, err := ui.Prompt("(e.g. ca.example.com[,10.1.2.3,etc.])",
			ui.WithSliceValue(ctx.StringSlice("dns")))
		if err != nil {
			return err
		}
		dnsNames, err := processDNSValue(dnsValue)
		if err != nil {
			return err
		}
		if useContext {
			ctxName := ctx.String("context")
			if ctxName == "" {
				ctxName = dnsNames[0]
			}
			ctxAuthority := ctx.String("authority")
			if ctxAuthority == "" {
				ctxAuthority = ctxName
			}
			ctxProfile := ctx.String("profile")
			if ctxProfile == "" {
				ctxProfile = ctxName
			}
			if err := step.Contexts().Add(&step.Context{
				Name:      ctxName,
				Profile:   ctxProfile,
				Authority: ctxAuthority,
			}); err != nil {
				return err
			}
			if err := step.Contexts().SaveCurrent(ctxName); err != nil {
				return errors.Wrap(err, "error storing new default context")
			}
			if err := step.Contexts().SetCurrent(ctxName); err != nil {
				return errors.Wrap(err, "error setting context '%s'")
			}
		}

		var address string
		if helm {
			ui.Println("What IP and port will your new CA bind to (it should match service.targetPort)?", ui.WithValue(ctx.String("address")))
		} else {
			ui.Println("What IP and port will your new CA bind to? (:443 will bind to 0.0.0.0:443)", ui.WithValue(ctx.String("address")))
		}
		address, err = ui.Prompt("(e.g. :443 or 127.0.0.1:443)",
			ui.WithValidateFunc(ui.Address()), ui.WithValue(ctx.String("address")))
		if err != nil {
			return err
		}

		// Only standalone deployments will create an initial provisioner.
		// Linked or hosted deployments will use an OIDC token as the first
		// deployment.
		var provisioner string
		if deploymentType == pki.StandaloneDeployment {
			ui.Println("What would you like to name the CA's first provisioner?", ui.WithValue(ctx.String("provisioner")))
			provisioner, err = ui.Prompt("(e.g. you@smallstep.com)",
				ui.WithValidateNotEmpty(), ui.WithValue(ctx.String("provisioner")))
			if err != nil {
				return err
			}
		}

		pkiOpts = append(pkiOpts,
			pki.WithAddress(address),
			pki.WithCaURL(caURL),
			pki.WithDNSNames(dnsNames),
			pki.WithDeploymentType(deploymentType),
		)
		if deploymentType == pki.StandaloneDeployment {
			pkiOpts = append(pkiOpts,
				pki.WithProvisioner(provisioner),
				pki.WithSuperAdminSubject(firstSuperAdminSubject),
			)
		}
		if deploymentType == pki.LinkedDeployment {
			pkiOpts = append(pkiOpts, pki.WithAdmin())
		} else if ctx.Bool("ssh") {
			pkiOpts = append(pkiOpts, pki.WithSSH())
		}
		if noDB {
			pkiOpts = append(pkiOpts, pki.WithNoDB())
		}
		if helm {
			pkiOpts = append(pkiOpts, pki.WithHelm())
		}

		// enable the admin API if the `--remote-management` flag is provided. This will
		// also result in the default provisioner being stored in the database and a default
		// admin (called `step` by default, but can be named with --admin-subject) to be
		// created for the default provisioner when the PKI is saved.
		if enableRemoteManagement {
			pkiOpts = append(pkiOpts, pki.WithAdmin())
		}

		// add a default ACME provisioner named `acme` if `--acme` flag is provided
		// and configuring a standalone CA. Not yet supported for linked deployments.
		if addDefaultACMEProvisioner && deploymentType == pki.StandaloneDeployment {
			pkiOpts = append(pkiOpts, pki.WithACME())
		}
	}

	if ra != "" || kmsName != "" {
		// RA mode will not have encrypted keys. With the exception of SSH keys,
		// but this is not common on RA mode.
		ui.Println("Choose a password for your first provisioner.", ui.WithValue(password))
	} else {
		// Linked CAs will use OIDC as a first provisioner.
		if pkiOnly || deploymentType != pki.StandaloneDeployment {
			ui.Println("Choose a password for your CA keys.", ui.WithValue(password))
		} else {
			ui.Println("Choose a password for your CA keys and first provisioner.", ui.WithValue(password))
		}
	}

	p, err := pki.New(casOptions, pkiOpts...)
	if err != nil {
		return err
	}

	pass, err := ui.PromptPasswordGenerate("[leave empty and we'll generate one]", ui.WithRichPrompt(), ui.WithValue(password))
	if err != nil {
		return err
	}

	if !pkiOnly && deploymentType == pki.StandaloneDeployment {
		// Generate provisioner key pairs.
		if len(provisionerPassword) > 0 {
			if err := p.GenerateKeyPairs(provisionerPassword); err != nil {
				return err
			}
		} else {
			if err := p.GenerateKeyPairs(pass); err != nil {
				return err
			}
		}
	}

	if casOptions.IsCreator {
		var root *apiv1.CreateCertificateAuthorityResponse
		ui.Println()
		// Generate root certificate if not set.
		if rootCrt == nil && rootKey == nil {
			ui.Print("Generating root certificate... ")
			root, err = p.GenerateRootCertificate(name, org, resource, pass)
			if err != nil {
				return err
			}
			ui.Println("done!")
		} else {
			ui.Printf("Copying root certificate... ")
			// Do not copy key in STEPPATH
			if err := p.WriteRootCertificate(rootCrt, nil, nil); err != nil {
				return err
			}
			root = p.CreateCertificateAuthorityResponse(rootCrt, rootKey)
			ui.Println("done!")
		}

		// Always generate the intermediate certificate
		ui.Printf("Generating intermediate certificate... ")
		time.Sleep(1 * time.Second)
		err = p.GenerateIntermediateCertificate(name, org, resource, root, pass)
		if err != nil {
			return err
		}
		ui.Println("done!")
	} else if err := p.GetCertificateAuthority(); err != nil {
		// Attempt to get the root certificate from RA.
		return err
	}

	if ctx.Bool("ssh") {
		ui.Printf("Generating user and host SSH certificate signing keys... ")
		if err := p.GenerateSSHSigningKeys(pass); err != nil {
			return err
		}
		ui.Println("done!")
	}

	if helm {
		return p.WriteHelmTemplate(os.Stdout)
	}
	return p.Save()
}

func NewClient(ctx *cli.Context, opts ...ca.ClientOption) (CaClient, error) {
	if ctx.Bool("offline") {
		caConfig := ctx.String("ca-config")
		if caConfig == "" {
			return nil, errs.InvalidFlagValue(ctx, "ca-config", "", "")
		}
		return NewOfflineCA(ctx, caConfig)
	}

	caURL, err := flags.ParseCaURL(ctx)
	if err != nil {
		return nil, err
	}
	root := ctx.String("root")
	if root == "" {
		root = pki.GetRootCAPath()
		if _, err := os.Stat(root); err != nil {
			return nil, errs.RequiredFlag(ctx, "root")
		}
	}
	opts = append([]ca.ClientOption{ca.WithRootFile(root)}, opts...)
	return ca.NewClient(caURL, opts...)
}

rootFile := pki.GetRootCAPath()
configFile := step.DefaultsFile()

if err = os.MkdirAll(filepath.Dir(rootFile), 0o700); err != nil {
	return errs.FileError(err, rootFile)
}

if err = os.MkdirAll(filepath.Dir(configFile), 0o700); err != nil {
	return errs.FileError(err, configFile)
}

// Serialize root
_, err = pemutil.Serialize(resp.RootPEM.Certificate, pemutil.ToFile(rootFile, 0o600))
if err != nil {
	return err
}
ui.Printf("The root certificate has been saved in %s.\n", rootFile)

// make sure to store the url with https
caURL, err = utils.CompleteURL(caURL)
if err != nil {
	return err
}

// Serialize defaults.json
bootConf := bootstrapConfig{
	CA:          caURL,
	Fingerprint: fingerprint,
	Root:        pki.GetRootCAPath(),
	Redirect:    bc.redirectURL,
}
if bc.minPasswordLength > 0 {
	bootConf.MinPasswordLength = bc.minPasswordLength
}
if bc.provisioner != "" {
	bootConf.Provisioner = bc.provisioner
}
b, err := json.MarshalIndent(bootConf, "", "  ")
if err != nil {
	return errors.Wrap(err, "error marshaling defaults.json")
}

ctx.Set("ca-url", caURL)
ctx.Set("fingerprint", fingerprint)
ctx.Set("root", rootFile)

if err := fileutil.WriteFile(configFile, b, 0o644); err != nil {
	return err
}

if step.Contexts().Enabled() {
	profileDefaultsFile := step.ProfileDefaultsFile()

	if err := os.MkdirAll(filepath.Dir(profileDefaultsFile), 0o700); err != nil {
		return errs.FileError(err, profileDefaultsFile)
	}

	if _, err := os.Stat(profileDefaultsFile); os.IsNotExist(err) {
		if err := os.WriteFile(profileDefaultsFile, []byte("{}"), 0o600); err != nil {
			return errs.FileError(err, profileDefaultsFile)
		}
		ui.Printf("The profile configuration has been saved in %s.\n", profileDefaultsFile)
	}
}

	app.Action = func(ctx *cli.Context) error {
		args := ctx.Args()
		if name := args.First(); name != "" {
			if file, err := plugin.LookPath(name); err == nil {
				return plugin.Run(ctx, file)
			}
			if u := plugin.GetURL(name); u != "" {
				//nolint:staticcheck // this is a top level error - capitalization is ok
				return fmt.Errorf("The plugin %q was not found on this system.\nDownload it from %s", name, u)
			}
			return cli.ShowCommandHelp(ctx, name)
		}
		return cli.ShowAppHelp(ctx)
	}
func LookPath(name string) (string, error) {
	fileName := "step-" + name + "-plugin"
	switch runtime.GOOS {
	case "windows":
		var exts []string
		x := os.Getenv(`PATHEXT`)
		if x != "" {
			for _, e := range strings.Split(strings.ToLower(x), `;`) {
				if e == "" {
					continue
				}
				if e[0] != '.' {
					e = "." + e
				}
				exts = append(exts, e)
			}
		} else {
			exts = []string{".com", ".exe", ".bat", ".cmd", ".ps1"}
		}
		for _, ext := range exts {
			path := filepath.Join(step.BasePath(), "plugins", fileName+ext)
			if _, err := os.Stat(path); err == nil { // #nosec G703 -- path to stat intentionally relies on (partial) user configuration
				return path, nil
			}
		}
	default:
		path := filepath.Join(step.BasePath(), "plugins", fileName)
		if _, err := os.Stat(path); err == nil {
			return path, nil
		}
	}
	return exec.LookPath(fileName)
}

// Run starts the given command with the arguments in the context and waits for
// it to complete.
func Run(ctx *cli.Context, file string) error {
	args := ctx.Args()
	cmdName := file

	// if running on Windows and (likely) a PowerShell script, invoke powershell
	// with the arguments instead of the plugin file directly.
	if runtime.GOOS == "windows" && strings.ToLower(filepath.Ext(file)) == ".ps1" {
		cmdName = "powershell"
		args = append([]string{args[0], "-noprofile", "-nologo", file}, args[1:]...)
	}

	cmd := exec.Command(cmdName, args[1:]...)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	return cmd.Run()
}

// GetURL returns the project or the download URL of a well-known plugin.
func GetURL(name string) string {
	switch name {
	case "kms":
		return "https://github.com/smallstep/step-kms-plugin"
	default:
		return ""
	}
}

func run() int {
	defer panicHandler()

	// initialize step environment.
	if err := step.Init(); err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		return 1
	}

	// create new instance of app
	app := newApp(os.Stdout, os.Stderr)

	if err := app.Run(os.Args); err != nil {
		var messenger interface {
			Message() string
		}
		if errors.As(err, &messenger) {
			if os.Getenv("STEPDEBUG") == "1" {
				fmt.Fprintf(os.Stderr, "%+v\n\n%s", err, messenger.Message())
			} else {
				fmt.Fprintln(os.Stderr, messenger.Message())
				fmt.Fprintln(os.Stderr, "Re-run with STEPDEBUG=1 for more info.")
			}
		} else {
			if os.Getenv("STEPDEBUG") == "1" {
				fmt.Fprintf(os.Stderr, "%+v\n", err)
			} else {
				fmt.Fprintln(os.Stderr, err)
			}
		}

		return 1
	}

	return 0
}

switch {
case isSSH && len(sans) > 0:
	return errs.IncompatibleFlagWithFlag(ctx, "ssh", "san")
case isHost && len(sans) > 0:
	return errs.IncompatibleFlagWithFlag(ctx, "host", "san")
case len(principals) > 0 && len(sans) > 0:
	return errs.IncompatibleFlagWithFlag(ctx, "principal", "san")
case !isSSH && isHost:
	return errs.RequiredWithFlag(ctx, "host", "ssh")
case !isSSH && len(principals) > 0:
	return errs.RequiredWithFlag(ctx, "principal", "ssh")
case cnfFile != "" && cnf != "":
	return errs.IncompatibleFlagWithFlag(ctx, "cnf-file", "cnf")
}

// Default token type is always a 'Sign' token.
var typ int
if isSSH {
	switch {
	case isRevoke:
		typ = cautils.SSHRevokeType
	case isRenew:
		typ = cautils.SSHRenewType
	case isRekey:
		typ = cautils.SSHRekeyType
	case isHost:
		typ = cautils.SSHHostSignType
		sans = principals
	default:
		typ = cautils.SSHUserSignType
		sans = principals
	}
} else {
	switch {
	case isRevoke:
		typ = cautils.RevokeType
	case isRenew:
		typ = cautils.RenewType
	default:
		typ = cautils.SignType
	}
}

caURL, err := flags.ParseCaURL(ctx)
if err != nil {
	return err
}

root := ctx.String("root")
if root == "" {
	root = pki.GetRootCAPath()
	if _, err := os.Stat(root); err != nil {
		return errs.RequiredFlag(ctx, "root")
	}
}

// Add options to create a confirmation claim if a CSR or SSH public key is
// passed.
var tokenOpts []cautils.Option
if cnfFile != "" {
	in, err := utils.ReadFile(cnfFile)
	if err != nil {
		return err
	}
	if isSSH {
		sshPub, _, _, _, err := ssh.ParseAuthorizedKey(in)
		if err != nil {
			return errors.Wrap(err, "error parsing ssh public key")
		}
		tokenOpts = append(tokenOpts, cautils.WithSSHPublicKey(sshPub))
	} else {
		csr, err := pemutil.ParseCertificateRequest(in)
		if err != nil {
			return errors.Wrap(err, "error parsing certificate request")
		}
		tokenOpts = append(tokenOpts, cautils.WithCertificateRequest(csr))
	}
} else if cnf != "" {
	tokenOpts = append(tokenOpts, cautils.WithConfirmationFingerprint(cnf))
}

templateData, err := flags.GetTemplateData(ctx)
if err != nil {
	return err
}
if templateData != nil {
	tokenOpts = append(tokenOpts, cautils.WithCustomAttributes(templateData))
}

// --san and --type revoke are incompatible. Revocation tokens do not support SANs.
if typ == cautils.RevokeType && len(sans) > 0 {
	return errs.IncompatibleFlagWithFlag(ctx, "san", "revoke")
}

// --offline doesn't support tokenOpts, so reject set/set-file
if offline {
	if len(ctx.StringSlice("set")) > 0 {
		return errs.IncompatibleFlagWithFlag(ctx, "offline", "set")
	}
	if ctx.String("set-file") != "" {
		return errs.IncompatibleFlagWithFlag(ctx, "offline", "set-file")
	}
}

// parse times or durations
notBefore, ok := flags.ParseTimeOrDuration(ctx.String("not-before"))
if !ok {
	return errs.InvalidFlagValue(ctx, "not-before", ctx.String("not-before"), "")
}
notAfter, ok := flags.ParseTimeOrDuration(ctx.String("not-after"))
if !ok {
	return errs.InvalidFlagValue(ctx, "not-after", ctx.String("not-after"), "")
}

// parse certificates durations
certNotBefore, err := api.ParseTimeDuration(ctx.String("cert-not-before"))
if err != nil {
	return errs.InvalidFlagValue(ctx, "cert-not-before", ctx.String("cert-not-before"), "")
}
certNotAfter, err := api.ParseTimeDuration(ctx.String("cert-not-after"))
if err != nil {
	return errs.InvalidFlagValue(ctx, "cert-not-after", ctx.String("cert-not-after"), "")
}

var token string
if offline {
	token, err = cautils.OfflineTokenFlow(ctx, typ, subject, sans, notBefore, notAfter, certNotBefore, certNotAfter)
	if err != nil {
		return err
	}
} else {
	token, err = cautils.NewTokenFlow(ctx, typ, subject, sans, caURL, root, notBefore, notAfter, certNotBefore, certNotAfter, tokenOpts...)
	if err != nil {
		return err
	}
}
if outputFile != "" {
	return fileutil.WriteFile(outputFile, []byte(token), 0o600)
}
fmt.Println(token)
return nil

func NewTokenFlow(ctx *cli.Context, tokType int, subject string, sans []string, caURL, root string, notBefore, notAfter time.Time, certNotBefore, certNotAfter provisioner.TimeDuration, opts ...Option) (string, error) {
	// Apply options to shared context
	for _, opt := range opts {
		opt.apply(&sharedContext)
	}

	// Get audience from ca-url
	audience, err := parseAudience(ctx, tokType)
	if err != nil {
		return "", err
	}

	// All provisioners use the same type of tokens to do a X.509 renewal.
	if tokType == RenewType {
		return generateRenewToken(ctx, audience, subject)
	}

	provisioners, err := pki.GetProvisioners(caURL, root)
	if err != nil {
		return "", err
	}
	p, err := provisionerPrompt(ctx, provisioners)
	if err != nil {
		return "", err
	}

	if subject == "" {
		// For OIDC provisioners the CA automatically generates the principals
		// from the email address.
		if _, ok := p.(*provisioner.OIDC); !ok {
			q := "What DNS names or IP addresses would you like to use? (e.g. internal.smallstep.com)"
			if tokType == SSHUserSignType {
				q = "What user principal would you like to use? (e.g. alice)"
			}
			subject, err = ui.Prompt(q, ui.WithValidateNotEmpty())
			if err != nil {
				return "", err
			}
		}
	}

	tokAttrs := tokenAttrs{
		subject:       subject,
		root:          root,
		caURL:         caURL,
		audience:      audience,
		sans:          sans,
		notBefore:     notBefore,
		notAfter:      notAfter,
		certNotBefore: certNotBefore,
		certNotAfter:  certNotAfter,
	}

	switch p := p.(type) {
	case *provisioner.JWK: // Get the step standard JWT.
		return generateJWKToken(ctx, p, tokType, tokAttrs)
	case *provisioner.OIDC: // Run step oauth.
		return generateOIDCToken(ctx, p)
	case *provisioner.X5C: // Get a JWT with an X5C header and signature.
		return generateX5CToken(ctx, p, tokType, tokAttrs)
	case *provisioner.Nebula:
		return generateNebulaToken(ctx, p, tokType, tokAttrs)
	case *provisioner.SSHPOP: // Generate a SSHPOP token using an ssh cert + key.
		return generateSSHPOPToken(ctx, p, tokType, tokAttrs)
	case *provisioner.K8sSA: // Get the Kubernetes service account token.
		return generateK8sSAToken(ctx)
	case *provisioner.GCP: // Do the identity request to get the token.
		sharedContext.DisableCustomSANs = p.DisableCustomSANs
		return p.GetIdentityToken(subject, caURL)
	case *provisioner.AWS: // Do the identity request to get the token.
		sharedContext.DisableCustomSANs = p.DisableCustomSANs
		return p.GetIdentityToken(subject, caURL)
	case *provisioner.Azure: // Do the identity request to get the token.
		sharedContext.DisableCustomSANs = p.DisableCustomSANs
		return p.GetIdentityToken(subject, caURL)
	case *provisioner.ACME: // Return an error with the provisioner ID.
		return "", &ACMETokenError{p.GetName()}
	case *provisioner.SCEP:
		return "", &SCEPTokenError{p.GetName()}
	default:
		return "", errors.Errorf("unknown provisioner type %T", p)
	}
}

func ReadInput(prompt string) ([]byte, error) {
	st, err := stdin.Stat()
	if err != nil {
		return nil, errors.Wrap(err, "error reading data")
	}

	if st.Size() == 0 && st.Mode()&os.ModeNamedPipe == 0 {
		return ui.PromptPassword(prompt)
	}

	return ReadAll(stdin)
}

// ReadFile returns the contents of the file identified by name. It reads from
// STDIN if name is a hyphen ("-").
func ReadFile(name string) (b []byte, err error) {
	if name == stdinFilename {
		name = "/dev/stdin"
		b, err = io.ReadAll(stdin)
	} else {
		var contents []byte
		contents, err = os.ReadFile(name) // #nosec G703 -- file intended to be provided by user
		if err != nil {
			return nil, errs.FileError(err, name)
		}
		b, err = io.ReadAll(utfbom.SkipOnly(bytes.NewReader(contents)))
	}
	if err != nil {
		return nil, errs.FileError(err, name)
	}
	return b, nil
}

func bootstrapAction(ctx *cli.Context) error {
	caURL, err := flags.ParseCaURLIfExists(ctx)
	if err != nil {
		return err
	}
	fingerprint := strings.TrimSpace(ctx.String("fingerprint"))
	team := ctx.String("team")
	teamAuthority := ctx.String("team-authority")

	switch {
	case team != "" && caURL != "":
		return errs.IncompatibleFlagWithFlag(ctx, "team", "ca-url")
	case team != "" && fingerprint != "":
		return errs.IncompatibleFlagWithFlag(ctx, "team", "fingerprint")
	case team != "" && teamAuthority != "":
		return cautils.BootstrapTeamAuthority(ctx, team, teamAuthority)
	case team != "":
		return cautils.BootstrapTeamAuthority(ctx, team, "ssh")
	case teamAuthority != "":
		return errs.RequiredWithFlag(ctx, "team-authority", "team")
	case caURL == "":
		return errs.RequiredFlag(ctx, "ca-url")
	case fingerprint == "":
		return errs.RequiredFlag(ctx, "fingerprint")
	default:
		return cautils.BootstrapAuthority(ctx, caURL, fingerprint)
	}
}

func certificateAction(ctx *cli.Context) error {
	if err := errs.MinMaxNumberOfArguments(ctx, 2, 3); err != nil {
		return err
	}

	// Allow two arguments with the attestation uri.
	if ctx.NArg() == 2 && ctx.String("attestation-uri") == "" {
		return errs.TooFewArguments(ctx)
	}

	args := ctx.Args()
	subject := args.Get(0)
	crtFile, keyFile := args.Get(1), args.Get(2)

	tok := ctx.String("token")
	offline := ctx.Bool("offline")
	sans := ctx.StringSlice("san")

	switch {
	case offline && tok != "":
		// offline and token are incompatible because the token is generated before
		// the start of the offline CA.
		return errs.IncompatibleFlagWithFlag(ctx, "offline", "token")
	case ctx.String("attestation-uri") != "" && ctx.String("kms") != "":
		// attestation-uri and kms are incompatible because the ACME-DA flow
		// expects all necessary parameters in the attestation-uri, and having
		// both can be confusing.
		return errs.IncompatibleFlagWithFlag(ctx, "attestation-uri", "kms")
	}

	// certificate flow unifies online and offline flows on a single api
	flow, err := cautils.NewCertificateFlow(ctx)
	if err != nil {
		return err
	}

	if tok == "" {
		// Use the ACME protocol with a different certificate authority.
		if ctx.IsSet("acme") {
			return cautils.ACMECreateCertFlow(ctx, "")
		}
		if tok, err = flow.GenerateToken(ctx, subject, sans); err != nil {
			var acmeTokenErr *cautils.ACMETokenError
			if errors.As(err, &acmeTokenErr) {
				return cautils.ACMECreateCertFlow(ctx, acmeTokenErr.Name)
			}
			return err
		}
	}

	req, pk, err := flow.CreateSignRequest(ctx, tok, subject, sans)
	if err != nil {
		return err
	}

	jwt, err := token.ParseInsecure(tok)
	if err != nil {
		return err
	}

	switch jwt.Payload.Type() {
	case token.JWK: // Validate that subject matches the CSR common name.
		if ctx.String("token") != "" && len(sans) > 0 {
			return errs.MutuallyExclusiveFlags(ctx, "token", "san")
		}
		if !strings.EqualFold(subject, req.CsrPEM.Subject.CommonName) {
			return errors.Errorf("token subject '%s' and argument '%s' do not match", req.CsrPEM.Subject.CommonName, subject)
		}
	case token.OIDC, token.AWS, token.GCP, token.Azure, token.K8sSA:
		// Common name will be validated on the server side, it depends on
		// server configuration.
	default:
		return errors.New("token is not supported")
	}

	if err := flow.Sign(ctx, tok, req.CsrPEM, crtFile); err != nil {
		return err
	}

	_, err = pemutil.Serialize(pk, pemutil.ToFile(keyFile, 0600))
	if err != nil {
		return err
	}

	ui.PrintSelected("Certificate", crtFile)
	ui.PrintSelected("Private Key", keyFile)
	return nil
}

func (af *acmeFlow) GetCertificate() ([]*x509.Certificate, error) {
	var (
		err             error
		newOrderRequest interface{}
		dnsNames        []string
		ips             []net.IP
	)

	attestationURI := af.ctx.String("attestation-uri")
	if attestationURI == "" {
		newOrderRequest, dnsNames, ips, err = createNewOrderRequest(af.ctx, af.acmeDir, af.subject, af.sans)
		if err != nil {
			return nil, err
		}
	} else {
		// parse times or durations
		nbf, naf, err := flags.ParseTimeDuration(af.ctx)
		if err != nil {
			return nil, err
		}

		// We currently do not accept other SANs with attestation certificates.
		newOrderRequest = acmeAPI.NewOrderRequest{
			Identifiers: []acme.Identifier{{
				Type:  "permanent-identifier",
				Value: af.subject,
			}},
			NotBefore: nbf.Time(),
			NotAfter:  naf.Time(),
		}
	}

	orderPayload, err := json.Marshal(newOrderRequest)
	if err != nil {
		return nil, errors.Wrap(err, "error marshaling order request")
	}

	ops, err := af.getClientTruststoreOption(af.ctx.IsSet("acme"))
	if err != nil {
		return nil, err
	}

	ac, err := ca.NewACMEClient(af.acmeDir, af.ctx.StringSlice("contact"), ops)
	if err != nil {
		return nil, errors.Wrapf(err, "error initializing ACME client with server %s", af.acmeDir)
	}

	o, err := ac.NewOrder(orderPayload)
	if err != nil {
		return nil, errors.Wrapf(err, "error creating new ACME order")
	}

	if err := authorizeOrder(af.ctx, ac, o, af); err != nil {
		return nil, err
	}

	if af.csr == nil {
		var signer crypto.Signer
		var template *x509.CertificateRequest
		switch {
		case attestationURI == "":
			insecure := af.ctx.Bool("insecure")
			kty, crv, size, err := utils.GetKeyDetailsFromCLI(af.ctx, insecure, "kty", "curve", "size")
			if err != nil {
				return nil, err
			}
			signer, err = keyutil.GenerateSigner(kty, crv, size)
			if err != nil {
				return nil, errors.Wrap(err, "error generating private key")
			}
			af.priv = signer
			template = &x509.CertificateRequest{
				Subject: pkix.Name{
					CommonName: af.subject,
				},
				DNSNames:    dnsNames,
				IPAddresses: ips,
			}
		case af.tpmSigner != nil:
			signer = af.tpmSigner
			template = &x509.CertificateRequest{
				Subject: pkix.Name{
					CommonName: af.subject,
				},
				// TODO(hs): add PermanentIdentifier extension?
				// TODO(hs): add SKAE extension?
			}
		default:
			signer, err = cryptoutil.CreateSigner(attestationURI, attestationURI)
			if err != nil {
				return nil, err
			}
			template = &x509.CertificateRequest{
				Subject: pkix.Name{
					CommonName: af.subject,
				},
			}
		}

		csrBytes, err := x509.CreateCertificateRequest(rand.Reader, template, signer)
		if err != nil {
			return nil, errors.Wrap(err, "error creating certificate request")
		}
		af.csr, err = x509.ParseCertificateRequest(csrBytes)
		if err != nil {
			return nil, errors.Wrap(err, "error parsing certificate request")
		}
	}

	fo, err := finalizeOrder(ac, o, af.csr)
	if err != nil {
		return nil, err
	}

	leaf, chain, err := ac.GetCertificate(fo.CertificateURL)
	if err != nil {
		return nil, errors.Wrapf(err, "error getting certificate")
	}

	fullChain := append([]*x509.Certificate{leaf}, chain...)

	// TODO: refactor this to be cleaner by passing the TPM and/or key around
	// instead of creating a new instance.
	if af.tpmSigner != nil {
		attestationURI := af.ctx.String("attestation-uri")
		tpmStorageDirectory := af.ctx.String("tpm-storage-directory")

		keyName, attURI, err := parseTPMAttestationURI(attestationURI)
		if err != nil {
			return nil, fmt.Errorf("failed parsing --attestation-uri: %w", err)
		}

		tpmOpts := []tpm.NewTPMOption{
			tpm.WithStore(tpmstorage.NewDirstore(tpmStorageDirectory)),
		}
		if device := attURI.Get("device"); device != "" {
			tpmOpts = append(tpmOpts, tpm.WithDeviceName(device))
		}

		t, err := tpm.New(tpmOpts...)
		if err != nil {
			return nil, fmt.Errorf("failed initializing TPM: %w", err)
		}

		ctx := tpm.NewContext(context.Background(), t)
		key, err := t.GetKey(ctx, keyName)
		if err != nil {
			return nil, fmt.Errorf("failed getting TPM key: %w", err)
		}
		if err = key.SetCertificateChain(ctx, fullChain); err != nil {
			return nil, fmt.Errorf("failed storing certificate with TPM key: %w", err)
		}
	}

	return fullChain, nil
}

func newACMEFlow(ctx *cli.Context, ops ...acmeFlowOp) (*acmeFlow, error) {
	// Offline mode is not supported for ACME protocol
	if ctx.Bool("offline") {
		return nil, errors.New("offline mode and ACME are mutually exclusive")
	}
	// One of --standalone or --webroot must be selected for use with ACME protocol.
	isStandalone, webroot := ctx.Bool("standalone"), ctx.String("webroot")
	switch {
	case isStandalone && webroot != "":
		return nil, errs.MutuallyExclusiveFlags(ctx, "standalone", "webroot")
	case !isStandalone && webroot == "":
		if err := ctx.Set("standalone", "true"); err != nil {
			return nil, errors.Wrap(err, "error setting 'standalone' value in cli ctx")
		}
	}

	af := new(acmeFlow)
	for _, op := range ops {
		if err := op(af); err != nil {
			return nil, err
		}
	}
	if len(af.sans) == 0 {
		af.sans = []string{af.subject}
	}

	af.ctx = ctx

	af.acmeDir = ctx.String("acme")
	if af.acmeDir == "" {
		caURL, err := flags.ParseCaURL(ctx)
		if err != nil {
			return nil, err
		}
		if af.provisionerName == "" {
			return nil, errors.New("acme flow expected provisioner ID")
		}
		af.acmeDir = fmt.Sprintf("%s/acme/%s/directory", caURL, af.provisionerName)
	}

	return af, nil
}

	sans             = ctx.StringSlice("san")
	profile          = ctx.String("profile")
	templateFile     = ctx.String("template")
	bundle           = ctx.Bool("bundle")
	subtle           = ctx.Bool("subtle")
	skipCSRSignature = ctx.Bool("skip-csr-signature")
)

if ctx.IsSet("profile") && templateFile != "" {
	return errs.IncompatibleFlagWithFlag(ctx, "profile", "template")
}

if ctx.Bool("csr") && skipCSRSignature {
	return errs.IncompatibleFlagWithFlag(ctx, "csr", "skip-csr-signature")
}

// Read template if passed
var template string
if templateFile != "" {
	b, err := utils.ReadFile(templateFile)
	if err != nil {
		return err
	}
	template = string(b)
}

	// Use default template if empty
	if template == "" {
		template = x509util.DefaultCertificateRequestTemplate
	}

	// Create certificate request
	data := x509util.CreateTemplateData(subject, sans)
	data.SetUserData(userData)
	csr, err := x509util.NewCertificateRequest(priv, x509util.WithTemplate(template, data))
	if err != nil {
		return err
	}
	cr, err := csr.GetCertificateRequest()
	if err != nil {
		return err
	}

	block, err := pemutil.Serialize(cr)
	if err != nil {
		return err
	}

	// Save key and certificate request
	if keyFile != "" {
		if err := savePrivateKey(ctx, keyFile, priv, noPass); err != nil {
			return err
		}
	}

