			config: config.Config{
				DNSNames: []string{"ca.smallstep.com"},
			},
			tokType: SSHRekeyType,
			want:    "https://ca.smallstep.com/ssh/rekey",
		},
		{
			name: "ok/dns-renew",
			config: config.Config{
				DNSNames: []string{"ca.smallstep.com"},
			},
			tokType: RenewType,
			want:    "https://ca.smallstep.com/renew",
		},
